sys_variable_value.value:
(function execute(inputs, outputs) {

    var helper = new x_cesy_service_gr.cesyCcfHelper();

    // 1. Get CCF connection
    var connectionId = helper.getCCFConnectionFromAlias(inputs.connectionAlias);

    // 2. Get properties
    var props = helper.getCCFPropertiesAsMap(connectionId);

    var endpoint = props["x_cesy_service_gr.endpoint"];
    var token = props["x_cesy_service_gr.api.token"];

    // 3. Build REST call
    var rm = new sn_ws.RESTMessageV2();

    rm.setEndpoint(endpoint);
    rm.setHttpMethod("get");

    rm.setRequestHeader("Authorization", "Bearer " + token);

    var response = rm.execute();

    outputs.statusCode = response.getStatusCode();
    outputs.body = response.getBody();

})(inputs, outputs);

